import net.minecraft.world.entity.*;import net.minecraft.world.entity.animal.*;import net.minecraft.world.item.*;import net.minecraft.core.Registry;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerLevel;import org.millenaire.common.goal.*;import org.millenaire.common.entity.*;import org.millenaire.common.village.*;import org.millenaire.common.utilities.*;import java.util.*;
public class FishingShearingCheck{
 static sun.misc.Unsafe unsafe;static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static class TestSheep extends Sheep{public boolean baby,sheared,alive;public DyeColor color;public TestSheep(){super(EntityType.SHEEP,null);}public boolean isBaby(){return baby;}public boolean isAlive(){return alive;}public boolean isSheared(){return sheared;}public void setSheared(boolean b){sheared=b;}public DyeColor getColor(){return color;}}
 static TestSheep sheep(DyeColor c)throws Exception{var s=(TestSheep)unsafe.allocateInstance(TestSheep.class);s.alive=true;s.color=c;return s;}
 public static void main(String[] args)throws Exception{net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();var f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);unsafe=(sun.misc.Unsafe)f.get(null);var v=(MillVillager)unsafe.allocateInstance(MillVillager.class);v.level=(ServerLevel)unsafe.allocateInstance(ServerLevel.class);v.house=new Building();v.house.tags.add("sheeps");v.inventory=new HashMap<>();var shear=new GoalShearSheep();
 for(DyeColor c:DyeColor.values()){var s=sheep(c);WorldUtilities.animals=new ArrayList<>(List.of(s));check(shear.getDestination(v)!=null&&shear.isPossibleSpecific(v),"Eligible sheep "+c);shear.performAction(v);Item wool=Registry.ITEM.get(new ResourceLocation(c.getName()+"_wool"));check(v.inventory.getOrDefault(wool,0)==3&&s.sheared,"Correct color and quantity "+c);shear.performAction(v);check(v.inventory.get(wool)==3,"No double yield "+c);}
 int before=v.swings;for(int mode=0;mode<3;mode++){var s=sheep(DyeColor.WHITE);s.baby=mode==0;s.alive=mode!=1;s.sheared=mode==2;WorldUtilities.animals=new ArrayList<>(List.of(s));check(shear.getDestination(v)==null&&!shear.isPossibleSpecific(v),"Ineligible sheep excluded");shear.performAction(v);}check(v.swings==before,"No action for baby dead or sheared");
 var fish=new GoalFish();check(fish.buildingLimit.get(org.millenaire.common.item.InvItem.createInvItem(Items.COD))==128&&fish.buildingLimit.get(org.millenaire.common.item.InvItem.createInvItem(Items.COOKED_COD))==128,"Fishing limits");var empty=new Building();empty.tags.add("fishingspot");var stocked=new Building();stocked.tags.add("fishingspot");stocked.resources.sleeping.x=20;stocked.resources.fishingspots.add(new Point());v.house.buildings.addAll(List.of(empty,stocked));check(fish.getDestination(v)!=null&&fish.isPossibleSpecific(v),"Empty nearest spot skipped");stocked.tags.clear();check(fish.getDestination(v)==null&&!fish.isPossibleSpecific(v),"Availability agrees with tagged destinations");
 fish.getHeldItemsTravelling(v)[0].shrink(1);check(fish.getHeldItemsTravelling(v)[0].getCount()==1,"Fresh fishing rod stack");fish.performAction(v);check(v.inventory.get(Items.COD)==1,"Normal cod catch");var inuit=new GoalFishInuit();MillCommonUtilities.bonus=false;inuit.performAction(v);check(v.inventory.get(Items.COD)==2&&!v.inventory.containsKey(Items.BONE_BLOCK),"Inuit ordinary catch");MillCommonUtilities.bonus=true;inuit.performAction(v);check(v.inventory.get(Items.COD)==3&&v.inventory.get(Items.BONE_BLOCK)==1,"Inuit bonus branch");v.house=null;check(fish.getDestination(v)==null&&!fish.isPossibleSpecific(v)&&shear.getDestination(v)==null&&!shear.isPossibleSpecific(v)&&shear.performAction(v),"Missing building safe");
 System.out.println("PASS: actual fishing/Inuit/shearing classes with world/storage/entity fixtures: 16 wool colors x3, repeated shearing, baby/dead/sheared exclusion, cod limits/catch, Inuit bone branches, empty fishing points, tag consistency, stack isolation and null buildings. Live AI and inventory integration untested.");}}
